/// The summary the usage header prints, from the usage golden and the inventory.
pub fn summary(tool: &str) -> Option<&'static str> {
    match tool {
        "CountReads" => Some("Count and print to standard output (and optionally to a file) the total number of reads in a SAM/BAM/CRAM file"),
        "CountVariants" => Some("Counts variant records in a VCF file, regardless of filter status."),
        "PrintReads" => Some("Print reads in the SAM/BAM/CRAM file"),
        "ApplyBQSR" => Some("Apply base quality score recalibration"),
        "SelectVariants" => Some("Select a subset of variants from a VCF file"),
        "IndexFeatureFile" => Some("Creates an index for a feature file, e.g. VCF or BED file."),
        "GatherVcfsCloud" => Some("Gathers multiple VCF files from a scatter operation into a single VCF file. Input files must be supplied in genomic\norder and must not have events at overlapping positions."),
        "CountBases" => Some("Count bases in a SAM/BAM/CRAM file"),
        "FlagStat" => Some("Accumulate flag statistics given a BAM file"),
        "CountBasesInReference" => Some("Count the numbers of each base in a reference file"),
        "SplitIntervals" => Some("Split intervals into sub-interval files."),
        "Pileup" => Some("Prints read alignments in samtools pileup format"),
        "PreprocessIntervals" => Some("Prepares bins for coverage collection"),
        "PrintDistantMates" => Some("Unmaps reads with distant mates."),
        "GetSampleName" => Some("Emit a single sample name"),
        "CompareIntervalLists" => Some("Compare two interval lists to see if they are equal"),
        "FixMisencodedBaseQualityReads" => Some("Fix Illumina base quality scores in a SAM/BAM/CRAM file"),
        "CheckPileup" => Some("Compare GATK's internal pileup to a reference Samtools mpileup"),
        "AnnotateIntervals" => Some("Annotates intervals with GC content, mappability, and segmental-duplication content"),
        "FastaReferenceMaker" => Some("Create snippets of a fasta file"),
        "CollectReadCounts" => Some("Collects read counts at specified intervals"),
        "GetPileupSummaries" => Some("Tabulates pileup metrics for inferring contamination"),
        "UnmarkDuplicates" => Some("Clears the 0x400 duplicate SAM flag"),
        "CalculateContamination" => Some("Calculate the fraction of reads coming from cross-sample contamination"),
        "PrintReadsHeader" => Some("Print the header from a SAM/BAM/CRAM file"),
        "CallableLoci" => Some("Determine callable status of loci"),
        "ShiftFasta" => Some("Creates a shifted fasta file and shift_back file"),
        "RevertBaseQualityScores" => Some("Revert Quality Scores in a SAM/BAM/CRAM file"),
        "AddOriginalAlignmentTags" => Some("Adds Original Alignment tag and original mate contig tag"),
        "LeftAlignIndels" => Some("Left-aligns indels from reads in a SAM/BAM/CRAM file"),
        "DumpTabixIndex" => Some("Dumps a tabix index file."),
        "ReadAnonymizer" => Some("Replace bases in reads with reference bases."),
        "PrintFileDiagnostics" => Some("Print diagnostic information about a genomics file to stdout"),
        "SplitReads" => Some("Outputs reads from a SAM/BAM/CRAM by read group, sample and library name"),
        "ClipReads" => Some("Clip reads in a SAM/BAM/CRAM file"),
        "SplitNCigarReads" => Some("Split Reads with N in Cigar"),
        "MethylationTypeCaller" => Some("Identify methylated bases from bisulfite sequenced, methylation-aware BAMs"),
        "BaseRecalibrator" => Some("Generates recalibration table for Base Quality Score Recalibration (BQSR)"),
        "GtfToBed" => Some("Gencode GTF to BED"),
        "TransferReadTags" => Some("Incorporate read tags in a SAM file to that of a matching SAM file"),
        "PostProcessReadsForRSEM" => Some("Reorder reads before running RSEM"),
        "VariantsToTable" => Some("Extract fields from a VCF file to a tab-delimited table"),
        "CompareBaseQualities" => Some("Compares the base qualities of two SAM/BAM/CRAM files"),
        "RemoveNearbyIndels" => Some("(Internal) Remove indels from the VCF file that are close to each other."),
        "UpdateVCFSequenceDictionary" => Some("Updates the sequence dictionary in a variant file."),
        "PrintBGZFBlockInformation" => Some("Print information about the compressed blocks in a BGZF format file"),
        "CreateHadoopBamSplittingIndex" => Some("Create a Hadoop BAM splitting index and optionally a BAM index from a BAM file"),
        "FastaAlternateReferenceMaker" => Some("Create an alternative reference by combining a fasta with a vcf."),
        "CompareReferences" => Some("Display reference comparison as a tab-delimited table and summarize reference differences."),
        "CheckReferenceCompatibility" => Some("Check a BAM/VCF for compatibility against specified references."),
        "ComposeSTRTableFile" => Some("Composes a genome-wide STR location table used for DragSTR model auto-calibration"),
        "CalculateMixingFractions" => Some("(Internal) Calculate proportions of different samples in a pooled bam"),
        "AnnotateVcfWithExpectedAlleleFraction" => Some("(Internal) Annotate a vcf with expected allele fractions in pooled sequencing"),
        "AnnotateVcfWithBamDepth" => Some("(Internal) Annotate a vcf with a bam's read depth at each variant locus"),
        "CountFalsePositives" => Some("Count PASS variants"),
        "EvaluateInfoFieldConcordance" => Some("Evaluate concordance of info fields in an input VCF against a validated truth VCF"),
        "CallCopyRatioSegments" => Some("Calls copy-ratio segments as amplified, deleted, or copy-number neutral"),
        "VariantFiltration" => Some("Filter variant calls based on INFO and/or FORMAT annotations"),
        "CollectAllelicCounts" => Some("Collects reference and alternate allele counts at specified sites"),
        "FilterIntervals" => Some("Filters intervals based on annotations and/or count statistics"),
        "GetNormalArtifactData" => Some("Collects data for training normal artifact filter"),
        "ValidateVariants" => Some("Validate VCF"),
        "LeftAlignAndTrimVariants" => Some("Left align and trim vairants"),
        "GatherBQSRReports" => Some("Gathers scattered BQSR recalibration reports into a single file"),
        "Concordance" => Some("Evaluate concordance of an input VCF against a validated truth VCF"),
        "DepthOfCoverage" => Some("Generate coverage summary information for reads data"),
        "CalculateGenotypePosteriors" => Some("Calculate genotype posterior probabilities given family and/or known population genotypes"),
        "DenoiseReadCounts" => Some("Denoises read counts to produce denoised copy ratios"),
        "ValidateBasicSomaticShortMutations" => Some("Check variants against tumor-normal bams representing the same samples, though not the ones from the actual calls."),
        "PrintReadCounts" => Some("Prints count files for CNV determination."),
        "CollectSVEvidence" => Some("Gathers paired-end and split read evidence files for use in the GATK-SV pipeline."),
        "PathSeqBuildKmers" => Some("Builds set of host reference k-mers"),
        "PathSeqBuildReferenceTaxonomy" => Some("Builds a taxonomy datafile of the microbe reference"),
        "SVAnnotate" => Some("Adds gene overlap and variant consequence annotations to SV VCF from GATK-SV pipeline"),
        "ConvertHeaderlessHadoopBamShardToBam" => Some("Convert a headerless BAM shard into a readable BAM"),
        "CondenseDepthEvidence" => Some("Merges adjacent DepthEvidence records."),
        "PrintSVEvidence" => Some("Merges multiple sources of SV evidence records of some particular feature type into a single output file.  Inputs must\nbe locus-sorted.  Can also subset by regions or samples."),
        "SiteDepthtoBAF" => Some("Convert SiteDepth to BafEvidence"),
        "GatherTranches" => Some("Gathers scattered VQSLOD tranches into a single file"),
        "GatherPileupSummaries" => Some("Combine output files from GetPileupSummary in the order defined by a sequence dictionary"),
        "GatherNormalArtifactData" => Some("Combine output files from GetNormalArtifactData in the order defined by a sequence dictionary"),
        "MergeMutectStats" => Some("Merge the stats output by scatters of a single Mutect2 job"),
        "CombineSegmentBreakpoints" => Some("Combine the breakpoints of two segment files while preserving annotations.\nThis tool will load all segments into RAM.\nComments lines start with '#' or the data can be prepended by a SAM File Header (not both).\nOutput file comments will be the first segment file comments concatenated with the second file comments.\nSAMFileHeaders in the input seg files are supported and will be merged in the output.\nOutput seg file will have a SAMFileHeader, even if the inputs did not.  If neither input file has a SAMFileHeader, then\na reference must be specified."),
        "MergeAnnotatedRegions" => Some("Merge annotated genomic regions based entirely on contig and annotation value.  Column header order is not guaranteed to\nbe preserved. Reference is required and will superseded any sequence dictionary in the given seg/region files.  Sequence\ndictionary is optional on the input file, but will be included on the output.  Conflicts of annotations is resolved by\nsorting the values and inserting a delimiter.  THIS TOOL IS TOTALLY UNSUPPORTED"),
        "MergeAnnotatedRegionsByAnnotation" => Some("This simple tool will merge genomic regions (specified in a tsv) when given annotations (columns) contain exact values\nin neighboring segments and the segments are within a specified maximum genomic distance."),
        "TagGermlineEvents" => Some("A tool for tagging possible germline events in a tumor segment file.  The algorithm used is very simplistic.  Segments\ncalled as amplified or deleted in the normal are matched by breakpoints (+/- some padding) or reciprocal overlap."),
        "FilterVariantTranches" => Some("Apply tranche filtering"),
        "FilterFuncotations" => Some("Filter variants based on clinically-significant Funcotations."),
        "LearnReadOrientationModel" => Some("Get the maximum likelihood estimates of artifact prior probabilities in the orientation bias mixture model filter"),
        "AlleleFrequencyQC" => Some("Given a variant callset, it is common to calculate various quality control metrics. These metrics include the number of\nraw or filtered SNP counts; ratio of transition mutations to transversions; concordance of a particular sample's calls\nto a genotyping chip; number of singletons per sample; etc. Furthermore, it is often useful to stratify these metrics by\nvarious criteria like functional class (missense, nonsense, silent), whether the site is CpG site, the amino acid\ndegeneracy of the site, etc. VariantEval facilitates these calculations in two ways: by providing several built-in\nevaluation and stratification modules, and by providing a framework that permits the easy development of new evaluation\nand stratification modules."),
        "CalculateAverageCombinedAnnotations" => Some("Divides annotations that were summed across samples by genomicsDB by the number of samples with het or hom var calls.\nThis is an approximation of taking the average of these annotations."),
        "DownsampleByDuplicateSet" => Some("Discard a set fraction of duplicate sets from a UMI-grouped bam"),
        "ExampleMultiFeatureWalker" => Some("Example of a MultiFeatureWalker subclass."),
        "MTLowHeteroplasmyFilterTool" => Some("If too many low heteroplasmy sites pass other filters, then filter all low heteroplasmy sites"),
        "MergeMutect2CallsWithMC3" => Some("UNSUPPORTED.  FOR EVALUATION ONLY. Merge M2 (eval) calls with MC3 (truth)"),
        "NuMTFilterTool" => Some("Uses the median autosomal coverage and the allele depth to determine whether the allele might be a NuMT"),
        "ReferenceBlockConcordance" => Some("This tool evaluates two GVCF files against each other and produces three histograms:\nTruth block histogram: Indicates the number of occurrence of reference blocks with a given confidence score and length\nin the truth GVCF\nEval block histogram: Indicates the number of occurrence of reference blocks with a given confidence score and length in\nthe eval GVCF\nConfidence concordance histogram: Reflects the confidence scores of bases in reference blocks in the truth and eval VCF,\nrespectively. An entry of 10 at bin \"80,90\" means that 10 bases in the truth GVCF have a confidence score of 80 while\nthose same bases have a score of 90 in the eval GVCF.\nIn contrast to the Concordance tool, this tool considers all variants, regardless of passing or failing filters."),
        "ASEReadCounter" => Some("Generates table of filtered base counts at het sites for allele specific expression"),
        "ApplyVQSR" => Some(" Apply a score cutoff to filter variants based on a recalibration table"),
        "CalibrateDragstrModel" => Some("estimates the parameters for the DRAGstr model"),
        "CombineGVCFs" => Some("Merges one or more HaplotypeCaller GVCF files into a single GVCF with appropriate annotations"),
        "GnarlyGenotyper" => Some("Perform \"quick and dirty\" joint genotyping on one or more samples pre-called with HaplotypeCaller"),
        "ReblockGVCF" => Some("Condenses homRef blocks in a single-sample GVCF"),
        "GroupedSVCluster" => Some("Clusters structural variants grouping by type, size, and track overlap"),
        "JointGermlineCNVSegmentation" => Some("Combine segmented gCNV VCFs."),
        "SVCluster" => Some("Clusters structural variants"),
        "SVConcordance" => Some("Annotates structural variant genotype concordance"),
        "SVStratify" => Some("Annotates variants by SV type, size, and reference tracks"),
        "VCFComparator" => Some("Compare two VCFs, as for pipeline test updates"),
        "VariantAnnotator" => Some("Tool for adding annotations to VCF files"),
        "AddFlowBaseQuality" => Some("Prints reads from the input SAM/BAM/CRAM file to the SAM/BAM/CRAM file while adding a base quality attribute."),
        "AddFlowSNVQuality" => Some("Add SNV Quality to the flow-based CRAM"),
        "AnalyzeCovariates" => Some("Evaluate and compare base quality score recalibration (BQSR) tables"),
        "AnalyzeSaturationMutagenesis" => Some("(EXPERIMENTAL) Processes reads from a MITESeq or other saturation mutagenesis experiment."),
        "BwaMemIndexImageCreator" => Some("Create a BWA-MEM index image file for use with GATK BWA tools"),
        "CRAMIssue8768Detector" => Some("Analyze a CRAM file to check for base corruption caused by GATK issue 8768"),
        "CollectF1R2Counts" => Some("Collect F1R2 read counts for the Mutect2 orientation bias mixture model filter"),
        "CreateReadCountPanelOfNormals" => Some("Creates a panel of normals for read-count denoising"),
        "CreateSomaticPanelOfNormals" => Some("Make a panel of normals for use with Mutect2"),
        "ExtractVariantAnnotations" => Some("Extracts site-level variant annotations, labels, and other metadata from a VCF file to HDF5 files"),
        "FilterAlignmentArtifacts" => Some("Filter alignment artifacts from a vcf callset."),
        "FilterMutectCalls" => Some("Filter somatic SNVs and indels called by Mutect2"),
        "FlowFeatureMapper" => Some("Map/find features in BAM file, output VCF. Initially mapping SNVs"),
        "FlowPairHMMAlignReadsToHaplotypes" => Some("Produces readxhaplotype matrix with likelihoods of read / haplotype"),
        "FuncotateSegments" => Some("Functional annotation for segment files.  The output formats are not well-defined and subject to change."),
        "Funcotator" => Some("Functional Annotator"),
        "FuncotatorDataSourceDownloader" => Some("Data source downloader for Funcotator."),
        "GeneExpressionEvaluation" => Some("Evaluate gene expression from RNA-seq reads aligned to genome."),
        "GroundTruthReadsBuilder" => Some("Produces a flexible and robust ground truth set for base calling training"),
        "GroundTruthScorer" => Some("Score reads against a reference/ground truth"),
        "HaplotypeBasedVariantRecaller" => Some("Calculate likelihood matrix for each Allele in VCF against a set of Reads limited by a set of Haplotypes"),
        "LocalAssembler" => Some("Local assembler for SVs"),
        "ModelSegments" => Some("Models segmented copy ratios from denoised copy ratios and segmented minor-allele fractions from allelic counts"),
        "RampedHaplotypeCaller" => Some("Call germline SNPs and indels via local re-assembly of haplotypes (ramped version)"),
        "SplitCRAM" => Some("Splits CRAM files efficiently by taking advantage of their container based structure"),
        "VariantEval" => Some("General-purpose tool for variant evaluation (% in dbSNP, genotype concordance, Ti/Tv ratios, and a lot more)"),
        "VariantRecalibrator" => Some("Build a recalibration model to score variant quality for filtering purposes"),
        _ => None,
    }
}

